//! `{{name}}`: an Ostro workflow module (generated by `ostro init`).
//!
//! `ostro build` compiles it to a WebAssembly component (`wasm32-wasip2`);
//! `ostro deploy` uploads it to a server.

use std::time::Duration;

use ostro_sdk::prelude::*;

/// The input of `hello`.
#[derive(Debug, Deserialize)]
pub struct HelloInput {
    pub name: String,
}

/// The payload of the `approve` signal.
#[derive(Debug, Deserialize)]
pub struct Approval {
    #[serde(default)]
    pub ok: bool,
}

/// The output of `hello`.
#[derive(Debug, Serialize)]
pub struct HelloOutput {
    pub greeting: String,
    pub approved: bool,
}

/// A durable step: it runs at most once to a recorded outcome; replays return it.
#[step]
fn greet(name: &str) -> Result<String, StepError> {
    Ok(format!("hello {name}"))
}

/// Greets, sleeps for three days (a durable timer: it survives restarts and deploys),
/// then waits for the `approve` signal (no timeout).
#[workflow(name = "hello", version = 1)]
pub fn hello(ctx: &Ctx, input: HelloInput) -> Result<HelloOutput, WorkflowError> {
    let greeting = greet(&input.name)?;
    ctx.sleep(Duration::from_secs(3 * 24 * 60 * 60)).wait()?;
    let approval: Approval = ctx.wait_signal("approve", None).wait()?;
    Ok(HelloOutput {
        greeting,
        approved: approval.ok,
    })
}

// The component's exports exist only in the wasm32 build: `cargo test` links this crate
// for the host, where the WIT export symbols cannot be linked into a cdylib.
#[cfg(target_arch = "wasm32")]
ostro_sdk::export!(HelloWorkflow);
